import { useEffect, useState } from "react";
import Login from "./components/Login";
import ValidationList from "./components/ValidationList";
import "./App.css";

function App() {
  const [token, setToken] = useState(null);
  const [instanceUrl, setInstanceUrl] = useState(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const t = params.get("token");
    const i = params.get("instance");
    const code = params.get("code");

    if (code) {
      const codeVerifier = localStorage.getItem("code_verifier");
      console.log("Code:", code);
      console.log("Code Verifier:", codeVerifier);

      if (!codeVerifier) {
        console.error("No code verifier found in localStorage!");
        return;
      }

      // Exchange code for token via backend
      fetch(
        `http://localhost:5000/oauth/callback?code=${encodeURIComponent(code)}&code_verifier=${encodeURIComponent(codeVerifier)}`
      )
        .then((res) => res.json())
        .then((data) => {
          console.log("Token response:", data);
          if (data.token && data.instance) {
            setToken(data.token);
            setInstanceUrl(decodeURIComponent(data.instance));
            localStorage.removeItem("code_verifier");
            window.history.replaceState({}, document.title, "/");
          }
        })
        .catch((err) => console.error("Token exchange error:", err));
      return;
    }

    if (t && i) {
      setToken(t);
      setInstanceUrl(decodeURIComponent(i));
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  return (
    <div className="App">
      <h1>Salesforce Validation Rule Manager</h1>
      {!token ? (
        <Login />
      ) : (
        <ValidationList token={token} instanceUrl={instanceUrl} />
      )}
    </div>
  );
}

export default App;
